async function onMountedFn(ctx) {
  const { currentRoute } = ctx.$globalVars.$router;
  try {
    const result = await ctx.$requestFns.getReceives(currentRoute.query);
    ctx.setForm('formModel', result.data);
    var btnSubmit = ctx.getNode('Button::btn-submit1');
    var btnUnSubmit = ctx.getNode('Button::btn-cancel-submit1');
    var btnEdit = ctx.getNode('Button::btn-edit1');

    const isAudit = !!(result.data.qReceive?.isAudit);
    if (btnSubmit?.updateProps) btnSubmit.updateProps({ display: !isAudit });
    if (btnUnSubmit?.updateProps) btnUnSubmit.updateProps({ display: isAudit });
    if (btnEdit?.updateProps) btnEdit.updateProps({ disabled: isAudit });

    const data = (result.data.qReceiveMoreMaterials || []).map((item) => ({
      ...(item?.qReceiveMoreMaterial || {}),
      qReceivePhotos: Array.isArray(item?.qReceivePhotos) ? item.qReceivePhotos : []
    }));
    const tb = ctx.getNode('YqTableReport::view-material-table');
    if (tb) {
      tb.exposed.setData(data);
    }
  } catch (err) {
    ctx.$vueGlobal.$message.error('加载单据详情失败');
    console.error('加载详情报错：', err);
  }
}

