async function(ctx) {
  var selectedRow = ctx.$dataModels.formModel.qReceive;
 console.log('selectedRow', selectedRow) ; var btnSubmit = ctx.getNode('Button::btn-submit1');
  var btnUnSubmit = ctx.getNode('Button::btn-cancel-submit1');
  var btnEdit = ctx.getNode('Button::btn-edit1');
  if (btnSubmit?.updateProps) btnSubmit.updateProps({ loading: true });

  ctx.$vueGlobal.$msgbox.confirm('确认提交订单吗？', '确认提交', {
    confirmButtonText: '确定',
    cancelButtonText: '取消',
    type: 'warning'
  }).then(async () => {
    const flowConfig = ctx.$dataModels.flowConfig.singleTable;
    if (flowConfig?.flow) {
      try {
        const params = {
          flowModule: flowConfig,
          executeModel: {
            tenantId: ctx.$globalVars.$context.tenantId,
            fullId: ctx.$globalVars.$context.fullId,
            orgId: ctx.$globalVars.$context.orgId,
            orgName: ctx.$globalVars.$context.orgName,
            instanceId: selectedRow?.id,
            instanceCode: selectedRow?.orderCode,
            sender: {
              id: ctx.$globalVars.$context.userId,
              userName: ctx.$globalVars.$context.realName,
            },
          },
          userInfo: {
            id: ctx.$globalVars.$context.userId,
            userName: ctx.$globalVars.$context.realName,
          },
        };
        const res = await ctx.$globalVars.$http.post("/mb-sharedata/flow-helper/start-task", params);
        if (res.result?.result === true) {
          ctx.$vueGlobal.$message.success("流程发起成功");
        } else {
          ctx.$vueGlobal.$message.error(`流程发起失败${res.result?.message}`);
        }
      } catch (e) {
        ctx.$vueGlobal.$message.error("流程发起失败");
      }
    }

    await ctx.$requestFns.toggleStatus({
      id: selectedRow.id,
      orgId: selectedRow.orgId,
      isAudit: true,
      approved: 1,
      auditDate: ctx.$utils.formatDate(),
      auditor: ctx.$globalVars.$context.realName
    });
    selectedRow.isAudit=true;
    if (btnSubmit?.updateProps) btnSubmit.updateProps({ display: false });
    if (btnUnSubmit?.updateProps) btnUnSubmit.updateProps({ display: true });
    if (btnEdit?.updateProps) btnEdit.updateProps({ disabled: true });
    ctx.$vueGlobal.$message.success('提交成功');

  }).catch(() => {
    ctx.$vueGlobal.$message.info('取消提交');
  }).finally(() => {
    if (btnSubmit?.updateProps) btnSubmit.updateProps({ loading: false });
 });
}

async function(ctx) {
  var selectedRow = ctx.$dataModels.formModel.qReceive;
  if (!selectedRow || !selectedRow.id) {
    ctx.$vueGlobal.$message.warning('请选择要撤销提交的单据');
    return;
  }
  var btnSubmit = ctx.getNode('Button::btn-submit1');
  var btnUnSubmit = ctx.getNode('Button::btn-cancel-submit1');
  var btnEdit = ctx.getNode('Button::btn-edit1');
  if (btnUnSubmit?.updateProps) {
    btnUnSubmit.updateProps({ loading: true });
  }

  ctx.$vueGlobal.$msgbox.confirm('确认撤销提交该单据吗？', '撤销提交', {
    confirmButtonText: '确定',
    cancelButtonText: '取消',
    type: 'warning'
  }).then(async () => {
    const params = {
      tenantId: ctx.$globalVars.$context.tenantId,
      fullId: ctx.$globalVars.$context.fullId,
      orgId: ctx.$globalVars.$context.orgId,
      instanceId: selectedRow.id,
    };
    try {
      const checkRes = await ctx.$globalVars.$http.post("/mb-sharedata/flow-helper/can-cancel-submit", params);
      if (checkRes.result?.result === false) {
        ctx.$vueGlobal.$message.error("有进行中的流程任务，请先完成流程任务");
        throw new Error("不允许撤销提交");
      }
      const delRes = await ctx.$globalVars.$http.delete("/mb-sharedata/flow-task/delete-task-by-instance-id", params);
      if (delRes.result?.result === false) {
        ctx.$vueGlobal.$message.error("有进行中的流程任务，请先完成流程任务");
        throw new Error("删除流程任务失败");
      }
      await ctx.$requestFns.toggleStatus({
        id: selectedRow.id,
        orgId: selectedRow.orgId,
        isAudit: false,
        approved: 0,
        auditDate: ctx.$utils.formatDate(),
        auditor: ctx.$globalVars.$context.realName
      });
      selectedRow.isAudit = false;
      if (btnSubmit?.updateProps) btnSubmit.updateProps({ display: true });
      if (btnUnSubmit?.updateProps) btnUnSubmit.updateProps({ display: false });
      if (btnEdit?.updateProps) btnEdit.updateProps({ disabled: false });
      ctx.$vueGlobal.$message.success('撤销提交成功');
    } catch (e) {
      if (!e.message.includes("不允许撤销提交") && !e.message.includes("删除流程任务失败")) {
        ctx.$vueGlobal.$message.error("流程撤销异常，请稍后重试");
      }
    }
  }).catch(() => {
    ctx.$vueGlobal.$message.info('取消撤销提交');
  }).finally(() => {
    if (btnUnSubmit?.updateProps) {
      btnUnSubmit.updateProps({ loading: false });
    }
  });
}

