async function(ctx, payload) {  if (!payload.currentRow) {
    return;
  }
  const viewP = ctx.getNode('YqImageCardPreview::view-photo-preview');
  const photos = Array.isArray(payload.currentRow?.qReceivePhotos) ? payload.currentRow.qReceivePhotos : [];
  if (photos.length === 0) {
    if (viewP?.updateProps) {
      viewP?.updateProps({imageList: []});
    }
  } else {
    const data = ctx.$sharedFns.buildPhotoModelValue(photos);
    viewP?.updateProps({ imageList: data });
  }
}

